using HomeLibrary;
using Microsoft.AspNetCore.DataProtection;
using Microsoft.AspNetCore.DataProtection.KeyManagement;
using Microsoft.Extensions.DependencyInjection;
using System.Security.Cryptography;
using System.Security.Cryptography.X509Certificates;
using System.Text.Json;
using System.IO.Compression;
public static class PortableBackupTests {
 public static async Task Run(string root){
  void Check(bool ok,string message){if(!ok)throw new Exception(message);Console.WriteLine("PASS "+message);}
  Directory.CreateDirectory(root);var source=Path.Combine(root,"original");var destination=Path.Combine(root,"replacement");Directory.CreateDirectory(source);
  using var rsa=RSA.Create(2048);var certRequest=new CertificateRequest("CN=Disposable backup key protection",rsa,HashAlgorithmName.SHA256,RSASignaturePadding.Pkcs1);using var cert=certRequest.CreateSelfSigned(DateTimeOffset.UtcNow.AddDays(-1),DateTimeOffset.UtcNow.AddDays(3));
  var services=new ServiceCollection();services.AddLogging();services.AddDataProtection().SetApplicationName("HomeLibrary.Native.v1").PersistKeysToFileSystem(new DirectoryInfo(Path.Combine(source,"keyring"))).ProtectKeysWithCertificate(cert);using var provider=services.BuildServiceProvider();var protection=provider.GetRequiredService<IDataProtectionProvider>();var keys=provider.GetRequiredService<IKeyManager>();
  var secret=protection.CreateProtector("Migration fixture").Protect("PAIRED IDENTITY SECRET");File.WriteAllText(Path.Combine(source,"test.protected"),secret);
  using var store=new Store(source,protection);var change=(string action,object value)=>store.Apply(new(action,JsonSerializer.SerializeToElement(value,Library.Json),store.Read().Revision));change("addBook",new{isbn="9780140328721",title="Portable book",author="Test Author"});
  using var admins=new LocalAdministrators(source,protection);var enrollment=admins.SetupFile; // protected local account document generated by ordinary setup
  var liveXml=Directory.GetFiles(Path.Combine(source,"keyring"),"*.xml").ToDictionary(p=>Path.GetFileName(p)!,p=>File.ReadAllText(p));Check(liveXml.Values.Any(v=>v.Contains("encryptedSecret")),"source keyring really uses certificate-based machine-independent encryption fixture");
  var snapshots=new SnapshotGate();var backup=new CompleteBackup(source,new Settings(),snapshots,keys);var archive=Path.Combine(root,"portable.carribrary-backup");await backup.SaveScheduled("Strong portable test password!",archive,default);
  var manifest=CompleteBackupRecovery.Unpack(archive,destination,"Strong portable test password!");Check(manifest.Format==2&&manifest.KeyProtection==PortableKeyring.Protection,"portable manifest explicitly distinguishes replacement-computer recovery from legacy archives");
  // Destination has no source certificate: only the password-unpacked/reprotected keyring.
  var targetServices=new ServiceCollection();targetServices.AddLogging();var target=targetServices.AddDataProtection().SetApplicationName("HomeLibrary.Native.v1").PersistKeysToFileSystem(new DirectoryInfo(Path.Combine(destination,"data/keyring")));if(OperatingSystem.IsWindows())target.ProtectKeysWithDpapi(true);using var targetProvider=targetServices.BuildServiceProvider();
  Check(targetProvider.GetRequiredService<IDataProtectionProvider>().CreateProtector("Migration fixture").Unprotect(File.ReadAllText(Path.Combine(destination,"data/test.protected")))=="PAIRED IDENTITY SECRET","replacement host decrypts restored server secrets without original key-protection certificate");
  Check(liveXml.All(p=>File.ReadAllText(Path.Combine(source,"keyring",p.Key!))==p.Value),"portable export never weakens or rewrites source live key protection");
  Check(BackupVerification.Verify(archive,"Strong portable test password!") is {Portable:true,SameWindowsComputerRequired:false},"verification reports portable keys without claiming old archives are portable");
  var weekly=new PortableBackups(source,protection,backup);weekly.Configure(new(true,"Weekly portable password!","Weekly portable password!",true));var originals=Directory.CreateDirectory(Path.Combine(source,"portable-backups"));File.WriteAllText(Path.Combine(originals.FullName,"keep-my-manual-copy.carribrary-backup"),"OWNER FILE");
  for(var i=0;i<5;i++)Check(await weekly.Run(true,default),"managed portable backup completes before retention");
  var files=originals.GetFiles("Carribrary-portable-*.carribrary-backup");Check(files.Length==4&&File.Exists(Path.Combine(originals.FullName,"keep-my-manual-copy.carribrary-backup")),"retention keeps four managed archives and never deletes unrelated/manual files");
  Check(!await weekly.Run(false,default),"weekly timer does not create another backup before seven days");
  var stored=File.ReadAllBytes(Path.Combine(source,"portable-backup-settings.protected"));Check(!System.Text.Encoding.UTF8.GetString(stored).Contains("Weekly portable password!"),"unattended backup password is protected at rest and omitted from status");
  Check(!JsonSerializer.Serialize(weekly.Status()).Contains("Weekly portable password!"),"schedule status never returns the saved password");
  var duplicateId=Guid.NewGuid().ToString();Check(await weekly.Run(true,default,duplicateId)&&!await weekly.Run(true,default,duplicateId),"retrying the same manual backup request does not create duplicate archives or rotate twice");
  var stale=Path.Combine(originals.FullName,"Carribrary-portable-20000101-000000-"+Guid.NewGuid().ToString("N")+".carribrary-backup.tmp");File.WriteAllText(stale,"interrupted encrypted output");Check(!await weekly.Run(false,default)&&!File.Exists(stale),"stale managed partial output is removed on the next schedule check without creating another archive");
  files=originals.GetFiles("Carribrary-portable-*.carribrary-backup");var before=files.Select(f=>f.Name).Order().ToArray();File.WriteAllText(Path.Combine(source,"broken.sqlite"),"not a database");try{await weekly.Run(true,default);throw new Exception("Broken snapshot was accepted");}catch(LibraryError){}File.Delete(Path.Combine(source,"broken.sqlite"));Check(originals.GetFiles("Carribrary-portable-*.carribrary-backup").Select(f=>f.Name).Order().SequenceEqual(before)&&!originals.GetFiles("*.tmp").Any(),"failed backup retains all four completed archives and removes incomplete output");weekly.Configure(new(false));Check(!await weekly.Run(true,default),"disabled schedule creates no automatic archive");Check(originals.GetFiles("Carribrary-portable-*.carribrary-backup").Select(f=>f.Name).Order().SequenceEqual(before),"disabling retains existing backups");
  var routine=Path.Combine(source,"backups");for(var i=1;i<=20;i++)File.WriteAllText(Path.Combine(routine,$"scheduled-20260101-1200{i:00}-r{i}.hlbackup"),"fixture");for(var i=1;i<=10;i++)File.WriteAllText(Path.Combine(routine,$"daily-2026-01-{i:00}.hlbackup"),"fixture");File.WriteAllText(Path.Combine(routine,"manual-keep.hlbackup"),"fixture");File.WriteAllText(Path.Combine(routine,"before-upgrade-keep.hlbackup"),"fixture");store.PruneRoutineBackups("scheduled",16);store.PruneRoutineBackups("daily",7);Check(Directory.GetFiles(routine,"scheduled-*.hlbackup").Length==16&&Directory.GetFiles(routine,"daily-*.hlbackup").Length==7&&File.Exists(Path.Combine(routine,"manual-keep.hlbackup"))&&File.Exists(Path.Combine(routine,"before-upgrade-keep.hlbackup")),"routine retention caps scheduled/daily snapshots without touching manual or migration backups");
  Check(store.DeletionBackups().Count(p=>p.EndsWith(".carribrary-backup"))==4,"administrator account-data deletion preview includes managed portable archives");
  CompleteRecovery.PauseNotifications(source);Check(!File.Exists(Path.Combine(source,"portable-backup-settings.protected")),"recovered schedules are paused alongside historical email/push settings");
 }
}
